"""Domain-specific five-table hard problems (five of each domain's tables); independent aggregates avoid fanout."""


def reconciliation_recipe(model):
    s=model['slug'];mp=model['map'];fact,master,_=model['base']
    pk,fk,amt=mp['RecordID'],mp['PartyID'],mp['Amount']
    eligible=f'SELECT f.* FROM [{s}].[{fact}] f JOIN E e ON e.EventID=f.[{pk}]'
    totals=f'SELECT [{fk}] AS OwnerID,COUNT(*) AS EventCount,COUNT([{amt}]) AS KnownCount,SUM([{amt}]) AS TotalValue FROM Eligible GROUP BY [{fk}]'
    ctes=[('Eligible',eligible),('HeaderTotals',totals)]
    common='o.OwnerID,COALESCE(t.EventCount,0) AS EventCount,COALESCE(t.KnownCount,0) AS KnownCount,CASE WHEN t.OwnerID IS NULL THEN CAST(0 AS decimal(38,4)) ELSE t.TotalValue END AS TotalValue'
    source='FROM Owners o LEFT JOIN HeaderTotals t ON t.OwnerID=o.OwnerID'
    edge='Preserve every master owner. Header values are counted once despite multiple children;zero activity gives total0,active all-unknown headers give null. Use historical child prices where stated,not current catalog prices.'
    prefix='Use only original fact records whose primary keys appear in the analysis population. For aggregated analysis rows,this means their representative minimum source ID,not all contributors. Use original stored header values for this reconciliation,not the derived analysis value. '
    if s=='retail':
        ctes += [('Lines','SELECT e.CustomerID AS OwnerID,SUM(i.Quantity*i.UnitPrice) AS LineValue,COUNT(DISTINCT p.ProductID) AS DistinctProducts FROM Eligible e JOIN retail.OrderItems i ON i.OrderID=e.OrderID JOIN retail.Products p ON p.ProductID=i.ProductID GROUP BY e.CustomerID'),('Paid','SELECT e.CustomerID AS OwnerID,SUM(p.PaidAmount) AS PaidValue FROM Eligible e JOIN retail.Payments p ON p.OrderID=e.OrderID GROUP BY e.CustomerID')]
        task='For every Customers row,reconcile eligible Orders against OrderItems/Products and Payments. Return order/known counts,known OrderTotal sum,historical line value,paid value,outstanding=header total-paid and distinct products. Missing lines/payments are zero;unknown header total keeps outstanding unknown.'
        cols='OwnerID,EventCount,KnownCount,TotalValue,LineValue,PaidValue,Outstanding,DistinctProducts'
        report=f'SELECT {common},COALESCE(l.LineValue,0) AS LineValue,COALESCE(p.PaidValue,0) AS PaidValue,(CASE WHEN t.OwnerID IS NULL THEN 0 ELSE t.TotalValue END)-COALESCE(p.PaidValue,0) AS Outstanding,COALESCE(l.DistinctProducts,0) AS DistinctProducts {source} LEFT JOIN Lines l ON l.OwnerID=o.OwnerID LEFT JOIN Paid p ON p.OwnerID=o.OwnerID'
    elif s=='banking':
        ctes += [('Lending','SELECT l.AccountID AS OwnerID,SUM(l.Principal) AS LoanPrincipal,COUNT(*) AS LoanCount,SUM(CASE WHEN l.CustomerID<>a.CustomerID THEN 1 ELSE 0 END) AS LoanOwnerMismatch FROM banking.Loans l JOIN banking.Accounts a ON a.AccountID=l.AccountID GROUP BY l.AccountID')]
        task='For every Accounts row,return its customer and branch names,eligible Transactions count/known count/known amount sum,and separately the principal/count of all Loans referencing that account. Count loans whose CustomerID differs from the account owner. Account loan exposure is independent of transaction count;do not join transactions and loans before aggregating.'
        cols='OwnerID,CustomerName,BranchName,EventCount,KnownCount,TotalValue,LoanPrincipal,LoanCount,LoanOwnerMismatch'
        report=f'SELECT o.OwnerID,c.CustomerName,b.BranchName,COALESCE(t.EventCount,0) AS EventCount,COALESCE(t.KnownCount,0) AS KnownCount,CASE WHEN t.OwnerID IS NULL THEN CAST(0 AS decimal(38,4)) ELSE t.TotalValue END AS TotalValue,COALESCE(l.LoanPrincipal,0) AS LoanPrincipal,COALESCE(l.LoanCount,0) AS LoanCount,COALESCE(l.LoanOwnerMismatch,0) AS LoanOwnerMismatch {source} JOIN banking.Accounts a ON a.AccountID=o.OwnerID JOIN banking.Customers c ON c.CustomerID=a.CustomerID JOIN banking.Branches b ON b.BranchID=a.BranchID LEFT JOIN Lending l ON l.OwnerID=o.OwnerID'
    elif s=='pharma':
        ctes += [('Stock','SELECT e.SupplierID AS OwnerID,SUM(i.QuantityOnHand) AS StockUnits,SUM(i.QuantityOnHand*p.StandardCost) AS StandardStockValue,COUNT(DISTINCT w.WarehouseID) AS WarehouseCount FROM Eligible e JOIN pharma.Products p ON p.ProductID=e.ProductID JOIN pharma.Inventory i ON i.BatchID=e.BatchID JOIN pharma.Warehouses w ON w.WarehouseID=i.WarehouseID GROUP BY e.SupplierID'),('ByWarehouse','SELECT e.SupplierID AS OwnerID,w.WarehouseID,SUM(i.QuantityOnHand) AS Units,MAX(w.Capacity) AS Capacity FROM Eligible e JOIN pharma.Inventory i ON i.BatchID=e.BatchID JOIN pharma.Warehouses w ON w.WarehouseID=i.WarehouseID GROUP BY e.SupplierID,w.WarehouseID'),('OverCapacity','SELECT OwnerID,COUNT(*) AS OverCapacityWarehouses FROM ByWarehouse WHERE Units>Capacity GROUP BY OwnerID')]
        task='For every Suppliers row,return eligible Batches count/known count/sum BatchCost once per batch,inventory units,current product StandardCost*inventory units as a clearly labelled standard-value proxy,distinct stocked warehouses,and count of warehouses where that supplier\'s eligible inventory units alone exceed Capacity. Missing inventory means zero,not an absent supplier.'
        cols='OwnerID,EventCount,KnownCount,TotalValue,StockUnits,StandardStockValue,WarehouseCount,OverCapacityWarehouses'
        report=f'SELECT {common},COALESCE(x.StockUnits,0) AS StockUnits,COALESCE(x.StandardStockValue,0) AS StandardStockValue,COALESCE(x.WarehouseCount,0) AS WarehouseCount,COALESCE(c.OverCapacityWarehouses,0) AS OverCapacityWarehouses {source} LEFT JOIN Stock x ON x.OwnerID=o.OwnerID LEFT JOIN OverCapacity c ON c.OwnerID=o.OwnerID'
    elif s=='healthcare':
        ctes += [('Rx','SELECT e.PatientID AS OwnerID,SUM(r.Quantity) AS PrescribedUnits,SUM(r.Quantity*m.UnitCost) AS MedicationCostProxy,COUNT(DISTINCT m.MedicationID) AS DistinctMedications FROM Eligible e JOIN healthcare.Prescriptions r ON r.EncounterID=e.EncounterID JOIN healthcare.Medications m ON m.MedicationID=r.MedicationID GROUP BY e.PatientID'),('Clinicians','SELECT e.PatientID AS OwnerID,COUNT(DISTINCT d.DoctorID) AS DoctorCount,COUNT(DISTINCT d.Specialty) AS SpecialtyCount FROM Eligible e JOIN healthcare.Doctors d ON d.DoctorID=e.DoctorID GROUP BY e.PatientID')]
        task='For every Patients row,reconcile eligible Encounters with Doctors,Prescriptions and Medications. Return encounter/known-charge counts,sum Charge once per encounter,distinct doctor/specialty counts,prescribed units,distinct medications and Quantity*current UnitCost as a labelled cost proxy. A medication price is not a clinical instruction or historical billed price.'
        cols='OwnerID,EventCount,KnownCount,TotalValue,DoctorCount,SpecialtyCount,PrescribedUnits,DistinctMedications,MedicationCostProxy'
        report=f'SELECT {common},COALESCE(c.DoctorCount,0) AS DoctorCount,COALESCE(c.SpecialtyCount,0) AS SpecialtyCount,COALESCE(r.PrescribedUnits,0) AS PrescribedUnits,COALESCE(r.DistinctMedications,0) AS DistinctMedications,COALESCE(r.MedicationCostProxy,0) AS MedicationCostProxy {source} LEFT JOIN Rx r ON r.OwnerID=o.OwnerID LEFT JOIN Clinicians c ON c.OwnerID=o.OwnerID'
    elif s=='oil':
        ctes += [('Lines','SELECT e.SiteID AS OwnerID,SUM(i.Quantity) AS LineUnits,SUM(i.Quantity*i.PricePerUnit) AS HistoricalLineValue,SUM(CASE WHEN i.PricePerUnit<>p.PricePerUnit THEN 1 ELSE 0 END) AS CatalogPriceDifferences FROM Eligible e JOIN oil.ShipmentItems i ON i.ShipmentID=e.ShipmentID JOIN oil.Products p ON p.ProductID=i.ProductID GROUP BY e.SiteID'),('Carriers','SELECT e.SiteID AS OwnerID,COUNT(DISTINCT c.CarrierID) AS CarrierCount,SUM(CASE WHEN c.Active=0 THEN 1 ELSE 0 END) AS InactiveCarrierShipments FROM Eligible e JOIN oil.Carriers c ON c.CarrierID=e.CarrierID GROUP BY e.SiteID')]
        task='For every Sites row,reconcile eligible Shipments and ShipmentItems/Products/Carriers. Return shipment/known counts,sum ShipmentValue once,detail quantity,historical line value,distinct carriers,shipments assigned to an inactive carrier,and detail rows whose historical price differs from current catalog price. Catalog differences are findings,not permission to replace historical prices.'
        cols='OwnerID,EventCount,KnownCount,TotalValue,LineUnits,HistoricalLineValue,CarrierCount,InactiveCarrierShipments,CatalogPriceDifferences'
        report=f'SELECT {common},COALESCE(l.LineUnits,0) AS LineUnits,COALESCE(l.HistoricalLineValue,0) AS HistoricalLineValue,COALESCE(c.CarrierCount,0) AS CarrierCount,COALESCE(c.InactiveCarrierShipments,0) AS InactiveCarrierShipments,COALESCE(l.CatalogPriceDifferences,0) AS CatalogPriceDifferences {source} LEFT JOIN Lines l ON l.OwnerID=o.OwnerID LEFT JOIN Carriers c ON c.OwnerID=o.OwnerID'
    elif s=='ecommerce':
        ctes += [('Lines','SELECT e.CustomerID AS OwnerID,SUM(i.Quantity*i.UnitPrice) AS LineValue,COUNT(DISTINCT p.ProductID) AS DistinctProducts FROM Eligible e JOIN ecommerce.OrderItems i ON i.OrderID=e.OrderID JOIN ecommerce.Products p ON p.ProductID=i.ProductID GROUP BY e.CustomerID'),('Paid','SELECT e.CustomerID AS OwnerID,SUM(p.PaidAmount) AS PaidValue FROM Eligible e JOIN ecommerce.Payments p ON p.OrderID=e.OrderID GROUP BY e.CustomerID'),('SellerMix','SELECT e.CustomerID AS OwnerID,COUNT(DISTINCT s.SellerID) AS SellerCount FROM Eligible e JOIN ecommerce.Sellers s ON s.SellerID=e.SellerID GROUP BY e.CustomerID')]
        task='For every Customers row,reconcile eligible Orders against Sellers,OrderItems/Products and Payments. Return order/known counts,known OrderTotal sum,historical line value,paid value (split payments added once per payment row),outstanding=header total-paid,distinct products and distinct sellers. Missing lines/payments are zero;unknown header total keeps outstanding unknown.'
        cols='OwnerID,EventCount,KnownCount,TotalValue,LineValue,PaidValue,Outstanding,DistinctProducts,SellerCount'
        report=f'SELECT {common},COALESCE(l.LineValue,0) AS LineValue,COALESCE(p.PaidValue,0) AS PaidValue,(CASE WHEN t.OwnerID IS NULL THEN 0 ELSE t.TotalValue END)-COALESCE(p.PaidValue,0) AS Outstanding,COALESCE(l.DistinctProducts,0) AS DistinctProducts,COALESCE(m.SellerCount,0) AS SellerCount {source} LEFT JOIN Lines l ON l.OwnerID=o.OwnerID LEFT JOIN Paid p ON p.OwnerID=o.OwnerID LEFT JOIN SellerMix m ON m.OwnerID=o.OwnerID'
    elif s=='retail_logistics':
        ctes += [('Latest','SELECT t.*,ROW_NUMBER() OVER(PARTITION BY PackageID ORDER BY ScanTime DESC,TrackingEventID DESC) AS Position FROM retail_logistics.TrackingEvents t'),('Delivered',"SELECT PackageID,MIN(ScanTime) AS FirstDeliveredAt,COUNT(*) AS DeliveredScans FROM retail_logistics.TrackingEvents WHERE EventStatus='Delivered' GROUP BY PackageID"),('ScanCounts','SELECT PackageID,COUNT(*) AS ScanCount FROM retail_logistics.TrackingEvents GROUP BY PackageID'),('Packages',"SELECT e.CustomerID AS OwnerID,COUNT(*) AS PackageCount,SUM(p.WeightKg) AS PackageWeightKg,SUM(CASE WHEN l.EventStatus='Delivered' THEN 1 ELSE 0 END) AS LatestDeliveredCount,SUM(CASE WHEN CAST(d.FirstDeliveredAt AS date)>p.PromisedDate THEN 1 ELSE 0 END) AS LateFirstDeliveryCount,SUM(CASE WHEN l.PackageID IS NULL THEN 1 ELSE 0 END) AS UnscannedCount,SUM(COALESCE(c.ScanCount,0)) AS TrackingScanCount FROM Eligible e JOIN retail_logistics.ShipmentPackages p ON p.ShipmentID=e.ShipmentID LEFT JOIN Latest l ON l.PackageID=p.PackageID AND l.Position=1 LEFT JOIN Delivered d ON d.PackageID=p.PackageID LEFT JOIN ScanCounts c ON c.PackageID=p.PackageID GROUP BY e.CustomerID"),('Services','SELECT e.CustomerID AS OwnerID,COUNT(DISTINCT c.ServiceLevel) AS ServiceLevelCount FROM Eligible e JOIN retail_logistics.Carriers c ON c.CarrierID=e.CarrierID GROUP BY e.CustomerID')]
        task='For every Customers row,reconcile eligible Shipments,Carriers,ShipmentPackages and TrackingEvents. Return shipment/known counts,sum FreightCharge once,distinct service levels,package count/weight,packages whose latest scan is Delivered,packages first delivered after PromisedDate,unscanned packages and scan count. Latest scan ties use greatest TrackingEventID;late delivery uses first Delivered scan. A package can have a delivery scan then a later non-delivery status.'
        cols='OwnerID,EventCount,KnownCount,TotalValue,ServiceLevelCount,PackageCount,PackageWeightKg,LatestDeliveredCount,LateFirstDeliveryCount,UnscannedCount,TrackingScanCount'
        report=f'SELECT {common},COALESCE(s.ServiceLevelCount,0) AS ServiceLevelCount,COALESCE(p.PackageCount,0) AS PackageCount,COALESCE(p.PackageWeightKg,0) AS PackageWeightKg,COALESCE(p.LatestDeliveredCount,0) AS LatestDeliveredCount,COALESCE(p.LateFirstDeliveryCount,0) AS LateFirstDeliveryCount,COALESCE(p.UnscannedCount,0) AS UnscannedCount,COALESCE(p.TrackingScanCount,0) AS TrackingScanCount {source} LEFT JOIN Packages p ON p.OwnerID=o.OwnerID LEFT JOIN Services s ON s.OwnerID=o.OwnerID'
    elif s=='retail_supply_chain':
        ctes += [('Net',"SELECT WarehouseID,ProductID,SUM(CASE Direction WHEN 'IN' THEN MovedUnits ELSE -MovedUnits END) AS NetUnits FROM Eligible GROUP BY WarehouseID,ProductID"),('Balances','SELECT b.WarehouseID AS OwnerID,SUM(b.OpeningQuantity) AS OpeningUnits,SUM(b.QuantityOnHand) AS StoredUnits,SUM(COALESCE(n.NetUnits,0)) AS SelectedNetUnits,SUM(b.QuantityOnHand-(b.OpeningQuantity+COALESCE(n.NetUnits,0))) AS QuantityDifference,SUM(b.QuantityOnHand*p.UnitCost) AS StandardStockValue FROM retail_supply_chain.StockBalances b JOIN retail_supply_chain.Products p ON p.ProductID=b.ProductID LEFT JOIN Net n ON n.WarehouseID=b.WarehouseID AND n.ProductID=b.ProductID GROUP BY b.WarehouseID'),('Missing','SELECT n.WarehouseID AS OwnerID,COUNT(*) AS MissingBalancePairs FROM Net n WHERE NOT EXISTS(SELECT 1 FROM retail_supply_chain.StockBalances b WHERE b.WarehouseID=n.WarehouseID AND b.ProductID=n.ProductID) GROUP BY n.WarehouseID'),('SupplierLead','SELECT e.WarehouseID AS OwnerID,MAX(s.LeadTimeDays) AS MaxLeadTimeDays FROM Eligible e JOIN retail_supply_chain.Suppliers s ON s.SupplierID=e.SupplierID GROUP BY e.WarehouseID')]
        task='For every Warehouses row,report eligible StockMovements count/known value count/sum MovementValue once. Separately reconcile every StockBalances warehouse/product pair using OpeningQuantity plus signed eligible MovedUnits(IN positive,OUT negative);return aggregate opening,stored,matched net units and stored-minus-expected difference. Return current Products.UnitCost*QuantityOnHand as a proxy,count of selected movement pairs with no balance,and maximum supplier LeadTimeDays among eligible movements. The selected movement slice may intentionally differ from the full snapshot.'
        cols='OwnerID,EventCount,KnownCount,TotalValue,OpeningUnits,StoredUnits,SelectedNetUnits,QuantityDifference,StandardStockValue,MissingBalancePairs,MaxLeadTimeDays'
        report=f'SELECT {common},COALESCE(b.OpeningUnits,0) AS OpeningUnits,COALESCE(b.StoredUnits,0) AS StoredUnits,COALESCE(b.SelectedNetUnits,0) AS SelectedNetUnits,COALESCE(b.QuantityDifference,0) AS QuantityDifference,COALESCE(b.StandardStockValue,0) AS StandardStockValue,COALESCE(m.MissingBalancePairs,0) AS MissingBalancePairs,l.MaxLeadTimeDays {source} LEFT JOIN Balances b ON b.OwnerID=o.OwnerID LEFT JOIN Missing m ON m.OwnerID=o.OwnerID LEFT JOIN SupplierLead l ON l.OwnerID=o.OwnerID'
    else:
        ctes += [('Fills','SELECT x.OrderID,SUM(x.ExecutedQuantity) AS ExecutedQuantity,SUM(x.ExecutedQuantity*x.ExecutionPrice) AS ExecutionValue FROM brokerage.Executions x GROUP BY x.OrderID'),('ExecutionTotals','SELECT e.AccountID AS OwnerID,SUM(COALESCE(f.ExecutedQuantity,0)) AS ExecutedQuantity,SUM(COALESCE(f.ExecutionValue,0)) AS ExecutionValue,SUM(CASE WHEN f.ExecutedQuantity>e.RequestedQuantity THEN 1 ELSE 0 END) AS OverfilledOrders FROM Eligible e LEFT JOIN Fills f ON f.OrderID=e.OrderID GROUP BY e.AccountID'),('Requested','SELECT e.AccountID AS OwnerID,SUM(e.RequestedQuantity) AS RequestedQuantity,COUNT(DISTINCT s.SecurityID) AS SecurityCount FROM Eligible e JOIN brokerage.Securities s ON s.SecurityID=e.SecurityID GROUP BY e.AccountID')]
        task='For every BrokerageAccounts row,join its Clients identity and reconcile eligible TradeOrders,Securities and Executions. Return client name,order/known-estimate counts,sum EstimatedValue once,requested/executed quantity,execution value from historical execution prices,quantity-weighted execution price,overfilled-order count and distinct securities. Pre-aggregate execution rows before testing each order for overfill;no fills means null weighted price.'
        cols='OwnerID,ClientName,EventCount,KnownCount,TotalValue,RequestedQuantity,ExecutedQuantity,ExecutionValue,WeightedExecutionPrice,OverfilledOrders,SecurityCount'
        report=f'SELECT o.OwnerID,c.ClientName,COALESCE(t.EventCount,0) AS EventCount,COALESCE(t.KnownCount,0) AS KnownCount,CASE WHEN t.OwnerID IS NULL THEN CAST(0 AS decimal(38,4)) ELSE t.TotalValue END AS TotalValue,COALESCE(r.RequestedQuantity,0) AS RequestedQuantity,COALESCE(x.ExecutedQuantity,0) AS ExecutedQuantity,COALESCE(x.ExecutionValue,0) AS ExecutionValue,CAST(x.ExecutionValue/NULLIF(x.ExecutedQuantity,0) AS decimal(28,6)) AS WeightedExecutionPrice,COALESCE(x.OverfilledOrders,0) AS OverfilledOrders,COALESCE(r.SecurityCount,0) AS SecurityCount {source} JOIN brokerage.BrokerageAccounts a ON a.AccountID=o.OwnerID JOIN brokerage.Clients c ON c.ClientID=a.ClientID LEFT JOIN Requested r ON r.OwnerID=o.OwnerID LEFT JOIN ExecutionTotals x ON x.OwnerID=o.OwnerID'
    return dict(task=prefix+task,ctes=ctes,report=report,columns=cols.split(','),order='OwnerID',edge=edge)
